do
	local add = {}
	add["forever/50-60/mount-hyjal"] = {
		["About 100 quests in Forever's new endgame zone, 57 to 59, then on to {zone:1451}."] = "Une centaine de quêtes dans la nouvelle zone de fin de parcours de Forever, de 57 à 59, puis direction {zone:1451}.",
		["Into {area:616}"] = "Vers le {area:616}",
		["New in Forever: this guide follows what players did on {area:616}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\n{area:616} lies south of {zone:1452}. Fly to {area:2255} (from Theramore on the Alliance route; the Horde route already ends there), bind your Hearthstone at the inn (partway through this guide {npc:256222} sends you to {area:493}, and the way there starts in {area:2255}), then ride south down the road through {area:2249} and on through {area:2256}, which leads up into {area:616}.\nCareful: elites stand along the whole way in. Frostmaul Giants and Preservers (59-60) flank the road through {area:2249}, and Hederine Slayers, Initiates and Manastalkers (57-58) line {area:2256} from its mouth to the zone line, with {npc:10201} (61) on its east side. Follow the arrows' line at full speed, never stop or fight on the way, and don't turn off it."] = "Nouveau dans Forever : ce guide suit ce que les joueurs ont fait sur le {area:616}. Une étape fausse ? Le signaler sur le Discord ou le GitHub de Polestar en nommant l'étape.\nLe {area:616} est au sud de {zone:1452}. Voler jusqu'à {area:2255} (depuis Theramore sur le parcours de l'Alliance ; celui de la Horde y finit déjà), lier la pierre de foyer à l'auberge (au milieu de ce guide, {npc:256222} envoie à {area:493}, et le chemin part de {area:2255}), puis descendre la route vers le sud par la {area:2249} et continuer par la {area:2256}, qui monte vers le {area:616}.\nAttention : des élites bordent tout le chemin. Des géants Frostmaul et des préservateurs (59-60) longent la route de la {area:2249}, et des tueurs, initiés et traqueurs de mana Hederine (57-58) bordent la {area:2256} de son entrée jusqu'à la limite de zone, avec {npc:10201} (61) sur son flanc est. Suivre la ligne des flèches à pleine vitesse, ne jamais s'arrêter ni combattre en route, et ne pas en sortir.",
		["North-west over the shrub field to {npc:249235}'s workshop on the slope above it. {quest:91923}, an elite (level 57), patrols the field, and {npc:248709}, an elite ancient (level 56), stands in its middle: give both room. Ghansurok, an elite chimaera (level 61), prowls around the workshop itself: see where he is before you ride up to {npc:249235}."] = "Au nord-ouest, à travers le champ d'arbustes, jusqu'à l'atelier de {npc:249235} sur la pente qui le domine. {quest:91923}, un élite (niveau 57), patrouille dans le champ, et {npc:248709}, un ancien élite (niveau 56), se tient en son milieu : garder ses distances avec les deux. Ghansurok, une chimère élite (niveau 61), rôde autour de l'atelier même : repérer où elle est avant de monter jusqu'à {npc:249235}.",
		["Seeds and owl eggs"] = "Graines et œufs de chouette",
		["Soil and venison"] = "Terre et venaison",
		["South down the west side of the shrub field to the ancients' outpost: kill the {npc:248395} you pass for {npc:249235}. {npc:260626}, the flight mistress, waits by the outpost; {npc:248367} and {npc:265586} stand with the ancient {npc:248366}."] = "Vers le sud par le côté ouest du champ d'arbustes jusqu'à l'avant-poste des anciens : tuer les {npc:248395} croisés en route, pour {npc:249235}. {npc:260626}, la maîtresse de vol, attend près de l'avant-poste ; {npc:248367} et {npc:265586} se tiennent avec l'ancien {npc:248366}.",
		["The ancients' outpost"] = "L'avant-poste des anciens",
		["The cog lies by the path south-west of the camp, on your way to {npc:256222}."] = "Le rouage est au bord du chemin au sud-ouest du camp, en allant vers {npc:256222}.",
		["The mouth of {area:2256}"] = "L'entrée de la {area:2256}",
		["The road in"] = "La route d'accès",
		["The road through {area:2249}"] = "La route de la {area:2249}",
		["The seeds and the owl eggs lie on the slopes between the Hermit's Abode and the road you came in on: search north-east up towards {npc:266803} and {npc:266802}."] = "Les graines et les œufs de chouette sont sur les pentes entre le refuge de l'Ermite et la route d'arrivée : chercher vers le nord-est, en montant vers {npc:266803} et {npc:266802}.",
		["The shrub field"] = "Le champ d'arbustes",
		["The three wrecks"] = "Les trois épaves",
		["The three wrecks {npc:256222} named lie at the east end of the fields: use the {item:269944} beside each, the catapult and the flying machine first, then the ballista a little north of them."] = "Les trois épaves que {npc:256222} a citées sont au bout est des champs : utiliser le {item:269944} à côté de chacune, la catapulte et la machine volante d'abord, puis la baliste un peu plus au nord.",
		["The untainted soil lies in the fields south and east of the outpost; Hyjal Stags graze there too, and their venison is for {npc:256222}'s stew.\nCareful: {npc:248709} (56), an elite treant, walks the fields to the south-east around 60,78: give him room."] = "La terre saine se trouve dans les champs au sud et à l'est de l'avant-poste ; des cerfs d'Hyjal y paissent aussi, et leur venaison sert au ragoût de {npc:256222}.\nAttention : {npc:248709} (56), un tréant élite, parcourt les champs au sud-est vers 60,78 : garder ses distances.",
		["Turn west here"] = "Tourner à l'ouest ici",
		["{item:269944}: the {npc:262036}"] = "{item:269944} : {npc:262036}",
		["{item:269944}: the {npc:266886}"] = "{item:269944} : {npc:266886}",
		["{item:269944}: the {npc:266887}"] = "{item:269944} : {npc:266887}",
		["{npc:249235}'s workshop"] = "L'atelier de {npc:249235}",
		["{npc:256222}, the hermit, lives at the Hermit's Abode a little further south-west. He takes the cog too."] = "{npc:256222}, l'ermite, vit au refuge de l'Ermite, un peu plus au sud-ouest. Il prend aussi le rouage.",
		["{npc:266803} (Alliance) and {npc:266802} (Horde) wait together by the road a little inside the zone."] = "{npc:266803} (Alliance) et {npc:266802} (Horde) attendent ensemble au bord de la route, un peu après l'entrée de la zone.",
		["{quest:91923} is elite (level 57) and patrols the shrub field: grouping up is advised."] = "{quest:91923} est un élite (niveau 57) qui patrouille dans le champ d'arbustes : mieux vaut être en groupe.",
		["{quest:92008}: for {npc:228216} in {area:2255}; you go there from {area:493} at the end of this guide"] = "{quest:92008} : pour {npc:228216} à {area:2255}, où le chemin passe depuis {area:493} à la fin de ce guide",
		["{quest:96796}: for {npc:249235}, on the way"] = "{quest:96796} : pour {npc:249235}, en chemin",
		["{quest:96830}: for {npc:244512} in {area:16848}, later in this guide; keep it"] = "{quest:96830} : pour {npc:244512} à {area:16848}, plus loin dans ce guide ; la garder",
		["{quest:96833}: for {npc:256222}, the hermit"] = "{quest:96833} : pour {npc:256222}, l'ermite",
	}
	add["forever/alliance/03-loch-modan"] = {
		["No Defias Brotherhood from Wiley (it starts with {npc:234}'s letter in {zone:1436}): skip {zone:1436}. North along the road from {area:87} to {zone:1453}: {npc:466} sits on his horse at the far end of the bridge outside the main gate. Then the gryphons in the {object:2096}, back to {area:69}.\nIf {npc:466} isn't at the arrow, he is walking his horse along the {area:1617} nearby: look along the avenue or wait a moment."] = "Pas de Confrérie défias chez Wiley (elle commence avec la lettre de {npc:234}, dans la {zone:1436}) : pas de passage par la {zone:1436}. Vers le nord par la route, de {area:87} jusqu'à {zone:1453} : {npc:466} est à cheval au bout du pont, devant la grande porte. Puis les griffons du {object:2096}, retour à {area:69}.\nSi {npc:466} n'est pas sous la flèche, il promène son cheval dans la {area:1617}, tout près : regarder le long de l'avenue ou attendre un moment.",
		["On the way to the harbour: {npc:4984}'s message goes to {npc:8997} in {area:442}, beside Terenthis, where the boat lands."] = "En allant au port : le message de {npc:4984} est pour {npc:8997} à {area:442}, à côté de Terenthis, là où le bateau accoste.",
		["{item:253247}: raise it beside Ylva, then hold the spot until {npc:269185} comes"] = "{item:253247} : la planter à côté d'Ylva, puis tenir la position jusqu'à l'arrivée de {npc:269185}",
		["{npc:332} is upstairs in the SI:7 building in {object:2100}: the stairs are hard to see at first. {npc:466} sits on his horse at the far end of the bridge outside the main gate, then back to the gryphons in the {object:2096}.\nIf {npc:466} isn't at the arrow, he is walking his horse along the {area:1617} nearby: look along the avenue or wait a moment."] = "{npc:332} est à l'étage du bâtiment du SI:7, dans la {object:2100} : l'escalier se voit mal au premier abord. {npc:466} est à cheval au bout du pont, devant la grande porte, puis retour aux griffons du {object:2096}.\nSi {npc:466} n'est pas sous la flèche, il promène son cheval dans la {area:1617}, tout près : regarder le long de l'avenue ou attendre un moment.",
	}
	add["forever/alliance/05-duskwood"] = {
		["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters and Bone Chewers (24-27) are the easier kills; Plague Spreaders and Brain Eaters (27-29) drop them too. {npc:522}, an elite, wanders the graves: keep away from him.\nCareful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds.\nCareful: {npc:503} (31) and {npc:771} (32), both rares, haunt the cemetery's north and west, and {npc:1200} (32, elite) keeps to the house at its western edge: leave them be."] = "Chaque goule de la moitié nord du {area:492} peut donner une côte : les dévoreurs de chair et les mâcheurs d'os (24-27) sont les plus faciles ; les propagateurs de peste et les mangeurs de cerveau (27-29) en donnent aussi. {npc:522}, un élite, erre entre les tombes : rester loin de lui.\nAttention : un {npc:948} lance {spell:3428} en mourant, ce qui fait venir d'autres ennemis.\nAttention : {npc:503} (31) et {npc:771} (32), deux rares, hantent le nord et l'ouest du cimetière, et {npc:1200} (32, élite) reste dans la maison à son bord ouest : les laisser tranquilles.",
		["For {npc:1212} in {zone:1453}'s Cathedral, on the walk north"] = "Pour {npc:1212}, à la cathédrale de {zone:1453}, sur la route du nord",
		["For {npc:1217} in {area:150} (the {zone:1437} guide)"] = "Pour {npc:1217} à {area:150} (le guide des {zone:1437})",
		["From level 28: the Skeletal Raiders, Healers and Warders stand in the west part of the {area:492}, just east of {npc:311}'s camp.\nCareful: The Warders are 28-29 and the skeletons stand close together: pull one at a time.\nCareful: {npc:522}, an elite (35), wanders these graves too, and {npc:771} (32, rare) haunts the west part: keep away from both."] = "Dès le niveau 28 : les pillards, guérisseurs et gardiens squelettes se tiennent dans la partie ouest du {area:492}, juste à l'est du camp de {npc:311}.\nAttention : les gardiens sont 28-29 et les squelettes sont serrés : les attirer un par un.\nAttention : {npc:522}, un élite (35), erre aussi entre ces tombes, et {npc:771} (32, rare) hante la partie ouest : rester loin des deux.",
		["Head north through Elwynn to {area:1519}; Mathias Shaw is at SI:7 in {object:2100}."] = "Vers le nord à travers Elwynn jusqu'à {area:1519} ; Mathias Shaw est au SI:7, dans la {object:2100}.",
		["North into {area:42}: {npc:276}'s house stands at the east end of town, on the way in."] = "Vers le nord jusqu'à {area:42} : la maison de {npc:276} est au bout est de la ville, à l'entrée.",
		["On into {zone:1453}: {npc:1212} stands in the Cathedral of Light, on the way to the gryphon master. His next quest is for {npc:1217} in {area:150}, where the flight lands."] = "Puis {zone:1453} : {npc:1212} se tient dans la cathédrale de la Lumière, sur le chemin du maître des griffons. Sa quête suivante est pour {npc:1217} à {area:150}, là où le vol arrive.",
		["On into {zone:1453}: {npc:297} (the arrow shows him) takes the letter; the {object:1561} beside him holds the next clue."] = "Puis {zone:1453} : {npc:297} (la flèche le montre) prend la lettre ; la {object:1561} à côté de lui contient l'indice suivant.",
		["On the way west to {npc:311}: Skeletal Fiends and Skeletal Horrors walk the cemetery's southern half, north of {area:94}. {npc:522}, an elite, wanders the graves: keep away from him."] = "En route vers l'ouest jusqu'à {npc:311} : des démons squelettes et des horreurs squelettes arpentent la moitié sud du cimetière, au nord de {area:94}. {npc:522}, un élite, erre entre les tombes : rester loin de lui.",
		["Skeletal Raiders"] = "Pillards squelettes",
		["The {npc:511} (26) hides in the small crypt by the {area:121}, south of {area:42}; the glass is inside."] = "{npc:511} (26) se cache dans la petite crypte près du {area:121}, au sud de {area:42} ; le miroir est à l'intérieur.",
		["{item:1946}: the {npc:511}, in the crypt of the cemetery just below"] = "{item:1946} : {npc:511}, dans la crypte du cimetière juste en dessous",
		["{item:910}, from the {object:1560} upstairs"] = "{item:910}, dans le {object:1560} à l'étage",
		["{npc:1212}, in the Cathedral of Light"] = "{npc:1212}, dans la cathédrale de la Lumière",
		["{npc:264}: the Plague Spreaders, with {npc:289}'s ghouls on the next trip west"] = "{npc:264} : les propagateurs de peste, avec les goules d'{npc:289} au prochain passage à l'ouest",
		["{npc:267}: for {npc:295} in {area:87}, on the walk north to {zone:1453}"] = "{npc:267} : pour {npc:295} à {area:87}, sur la route du nord vers {zone:1453}",
		["{npc:604}, for {quest:58}"] = "{npc:604}, pour {quest:58}",
		["{object:1561}, beside him"] = "{object:1561}, à côté de lui",
		["{quest:177}: the ogres of Vul'Gol, on your {zone:1431} return"] = "{quest:177} : les ogres de Vul'Gol, au prochain passage dans le {zone:1431}",
		["{quest:67}: west from {npc:311}'s camp over the border into {zone:1436} and on to {area:20}, where the {object:3643} stands among the Defias (15-18). Then hearth back to {area:42}."] = "{quest:67} : à l'ouest du camp de {npc:311}, passer la frontière de la {zone:1436} et continuer jusqu'à {area:20}, où le {object:3643} se trouve parmi les Défias (15-18). Puis pierre de foyer pour revenir à {area:42}.",
		["{quest:68}: {npc:267}, in the town hall, takes the footlocker's contents."] = "{quest:68} : {npc:267}, à l'hôtel de ville, prend le contenu du coffre.",
		["{quest:69}: {npc:295} is in {area:87}'s Lion's Pride Inn; the chest with the letter is upstairs."] = "{quest:69} : {npc:295} est à l'auberge de la Fierté du lion, à {area:87} ; le coffre avec la lettre est à l'étage.",
	}
	t.guides = type(t.guides) == "table" and t.guides or {}
	for id, list in pairs(add) do
		local g = t.guides[id]
		if type(g) ~= "table" then
			g = {}
			t.guides[id] = g
		end
		for en, fr in pairs(list) do
			if g[en] == nil or g[en] == "" then g[en] = fr end
		end
	end
end
